"""Generator for `_benchmark_names.py`."""

from __future__ import annotations

from pathlib import Path
from textwrap import dedent
from typing import TYPE_CHECKING

from mqt.bench.benchmarks import get_available_benchmark_names

if TYPE_CHECKING:
    from typing import TextIO


def generate(channel: TextIO) -> None:
    channel.write(
        dedent("""\
        # file generated by `_generate_benchmark_names.py`
        # don't change it directly
        \"""Benchmark names.\"""

        from __future__ import annotations

        from enum import Enum


        class BenchmarkName(str, Enum):  # enum.StrEnum introduced in Python 3.11
            \"""Enumeration of quantum benchmark algorithms available in ``mqt.bench``.

            This enumeration is generated with :func:`mqt.bench.benchmarks.get_available_benchmark_names`
            and tested in the test suite.
            \"""

    """)
    )
    names = get_available_benchmark_names()
    channel.writelines(f'    {name.upper()} = "{name}"\n' for name in names)


def main() -> None:
    with Path("_benchmark_names.py").open("w", encoding="UTF-8") as channel:
        generate(channel)


if __name__ == "__main__":
    main()
